function loadPaymentConfig(env) {
  if (!env.PAYMENT_GATEWAY_TIMEOUT_MS) {
    throw new Error("missing required config: PAYMENT_GATEWAY_TIMEOUT_MS");
  }
  const timeoutMs = Number(env.PAYMENT_GATEWAY_TIMEOUT_MS);
  if (!Number.isFinite(timeoutMs)) {
    throw new Error("invalid PAYMENT_GATEWAY_TIMEOUT_MS: must be a number");
  }
  return { timeoutMs };
}

