items.solution:
function validateRateLimit(requestsPerSecond) {
  if (typeof requestsPerSecond !== "number" || !Number.isFinite(requestsPerSecond)) {
    throw new Error("rateLimit must be a finite number");
  }
  if (requestsPerSecond <= 0 || requestsPerSecond > 100000) {
    throw new Error(`rateLimit out of sane range: ${requestsPerSecond}`);
  }
  return requestsPerSecond;
}

